from pathlib import Path
p=Path('workflow-engine.js'); s=p.read_text()
start=s.index('function registerArtifactBytes('); end=s.index('\nfunction selectedArtifacts',start)
old=s[start:end]
new="""function registerArtifactBytes(project,{stage=project.activeStage,artifactId,filename,mediaType,byteSize,sha256,lineage={},role='STAGE_ARTIFACT'}={}){
  ensureShape(project);if(!artifactId||!filename||!Number.isInteger(Number(byteSize))||Number(byteSize)<0||!/^[a-f0-9]{64}$/i.test(String(sha256||'')))throw new Error('Verified artifact identity is incomplete.');
  if(records(project,'artifacts',{active:false}).some(r=>recordId(r,'artifacts')===String(artifactId)))return records(project,'artifacts',{active:false}).find(r=>recordId(r,'artifacts')===String(artifactId));
  const stageNumber=Number(stage),scopedProductId=stageNumber===21?String(currentScope(project).productId||''):String(lineage?.productId||'');if(stageNumber===21&&!scopedProductId)throw new Error('Reserve the Stage 21 product execution before registering finished-product bytes.');
  const fields={FILENAME:String(filename),TYPE:String(mediaType||'application/octet-stream'),VERSION:'APPLICATION-CONTROLLED',BYTE_SIZE:Number(byteSize),SHA256:String(sha256).toLowerCase(),ROLE:role,STORAGE_REFERENCE:`indexeddb:${artifactId}`,AVAILABILITY:'BYTES_PERSISTED_AND_VERIFIED',NOTES:JSON.stringify({...lineage,...(scopedProductId?{productId:scopedProductId}:{})})};
  const definition=schema.RECORD_SCHEMAS.artifacts,id=String(artifactId),deviceTimestamp=now(),full={...fields,[definition.idField]:id};const recordScope=currentScope(project);if(scopedProductId)recordScope.productId=scopedProductId;const record={id,stage:stageNumber,createdAt:deviceTimestamp,updatedAt:deviceTimestamp,active:true,scope:recordScope,fields:full,...full,source:'APPLICATION_BYTES_VERIFIED'};refreshRecordHashes(record,'artifacts');project.projectData.artifacts.push(record);if(scopedProductId){const product=records(project,'products').find(r=>recordId(r,'products')===scopedProductId&&isActiveRecord(r));if(!product)throw new Error('Artifact lineage references a missing or inactive product.');const inventory=[...new Set([...safe(recordValue(product,'GENERATED_ARTIFACT_INVENTORY')),id])];product.fields={...(product.fields||{}),GENERATED_ARTIFACT_INVENTORY:inventory};product.GENERATED_ARTIFACT_INVENTORY=inventory;product.updatedAt=now();refreshRecordHashes(product,'products');}addHistory(project,'ARTIFACT_BYTES_REGISTERED',{stage:stageNumber,artifactId:id,byteSize:Number(byteSize),sha256:String(sha256).toLowerCase(),productId:scopedProductId||null});recalculate(project);return record;
}"""
s=s[:start]+new+s[end:]
start=s.index('function freezeBaseline('); end=s.index('\nfunction reserveProductExecution',start)
old=s[start:end]
new="""function freezeBaseline(project,{artifactIds=[],operatorLabel='HUMAN_OPERATOR',authorization='AUTHORIZED'}={}){
  ensureShape(project);const confirmation=recordsForCurrentScope(project,'confirmationRecords').filter(r=>upper(recordValue(r,'DETERMINATION'))==='SATISFIED').at(-1);if(!confirmation)throw new Error('A current successful unchanged confirmation is required before baseline freeze.');const currentIteration=records(project,'iterations').find(r=>recordId(r,'iterations')===String(project.job.CURRENT_ITERATION||'')&&isActiveRecord(r));if(!currentIteration||Number(currentIteration.stage)!==19)throw new Error('The current unchanged-confirmation iteration is required before baseline freeze.');const currentCandidateId=iterationCandidateId(project,recordId(currentIteration,'iterations')),currentCandidate=records(project,'candidateFreezes').find(r=>recordId(r,'candidateFreezes')===currentCandidateId&&isActiveRecord(r));if(!currentCandidate||!candidateComponentIdentity(project,currentCandidateId))throw new Error('The unchanged-confirmation iteration does not resolve to an active frozen candidate.');
  const candidateManifest=safe(recordValue(currentCandidate,'COMPONENT_MANIFEST')),candidateArtifactIds=candidateManifest.map(item=>String(item?.artifactId||'')).filter(Boolean);if(!candidateArtifactIds.length||new Set(candidateArtifactIds).size!==candidateArtifactIds.length)throw new Error('The unchanged candidate has no exact unique frozen artifact manifest.');const supplied=[...new Set(safe(artifactIds).map(String).filter(Boolean))];if(supplied.length&&(supplied.length!==candidateArtifactIds.length||supplied.some(id=>!candidateArtifactIds.includes(id))))throw new Error('Baseline selection must exactly match the unchanged candidate artifact manifest; unrelated or partial artifacts cannot be baselined.');const artifacts=selectedArtifacts(project,candidateArtifactIds);for(const item of candidateManifest){const artifact=artifacts.find(a=>recordId(a,'artifacts')===String(item.artifactId));if(!artifact||String(recordValue(artifact,'FILENAME'))!==String(item.filename)||Number(recordValue(artifact,'BYTE_SIZE'))!==Number(item.byteSize)||String(recordValue(artifact,'SHA256'))!==String(item.sha256)||String(recordValue(artifact,'STORAGE_REFERENCE'))!==String(item.storageReference))throw new Error(`Frozen candidate artifact ${item.artifactId||'UNKNOWN'} no longer matches its exact canonical byte identity.`);}
  const baselineId=allocateId(project,'baselines'),createdAt=now(),approvedVersions={inputVersion:project.job.CURRENT_INPUT_VERSION,sourceSetVersion:project.job.CURRENT_SOURCE_SET_VERSION,requirementsVersion:project.job.CURRENT_REQUIREMENTS_VERSION,testSuiteVersion:project.job.CURRENT_TEST_SUITE_VERSION,instructionVersion:project.job.CURRENT_INSTRUCTION_VERSION,iterationId:recordId(currentIteration,'iterations'),candidateId:currentCandidateId,hashes:Object.fromEntries(candidateManifest.map(a=>[a.artifactId,a.sha256]))};const fields={BASELINE_ID:baselineId,SUPPORTING_CONFIRMIRMATION_ID:undefined,SUPPORTING_CONFIRMATION_ID:recordId(confirmation,'confirmationRecords'),APPROVED_VERSIONS:approvedVersions,IMMUTABLE_ARTIFACT_RECORDS:candidateArtifactIds,HASHES:approvedVersions.hashes,HUMAN_AUTHORIZATION:authorization,AUTHORIZED_RECIPIENT_ROLES:'CURRENT AUTHORIZED ROLES',CONTROLLED_STORAGE:'INDEXEDDB VERIFIED BYTES',STATUS:'FROZEN',EVIDENCE:hash.sha256Value({approvedVersions,candidateManifest,operatorLabel})};delete fields.SUPPORTING_CONFIRMIRMATION_ID;const record={id:baselineId,stage:20,createdAt,active:true,scope:{...currentScope(project),baselineId},fields,...fields,source:'APPLICATION_DERIVATION'};record.contentSha256=hash.contentRecordSha256(record,'BASELINE_ID');record.recordSha256=hash.recordSha256(record);record.sha256=record.recordSha256;project.projectData.baselines.push(record);project.job.CURRENT_BASELINE_ID=baselineId;addHistory(project,'BASELINE_FROZEN',{stage:20,baselineId,artifactIds:candidateArtifactIds,candidateId:currentCandidateId,operatorLabel,identityAssurance:'SELF_ASSERTED'});recalculate(project);return record;
}"""
s=s[:start]+new+s[end:]
p.write_text(s)

p=Path('verify-complete.mjs'); s=p.read_text()
anchor='// Artifact identity is independent of file-selection order.\n'
test="""// Baseline bytes must be exactly the unchanged candidate manifest; Stage 21 bytes must bind to a reserved product.
{
  const p=project('JOB-ARTIFACT-AUTHORITY');p.job.CURRENT_INPUT_VERSION='INPUT-v001';p.job.CURRENT_SOURCE_SET_VERSION='SOURCE-SET-v001';p.job.CURRENT_REQUIREMENTS_VERSION='REQUIREMENTS-v001';p.job.CURRENT_TEST_SUITE_VERSION='TEST-SUITE-v001';p.job.CURRENT_INSTRUCTION_VERSION='INSTRUCTION-v001';
  for(const [id,name,sha] of [['ART-CANDIDATE','system/design.step','aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'],['ART-UNRELATED','other/design.step','bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb']])engine.registerArtifactBytes(p,{stage:10,artifactId:id,filename:name,mediaType:'application/octet-stream',byteSize:10,sha256:sha});
  const frozen=engine.freezeCandidate(p,{stage:10,artifactIds:['ART-CANDIDATE']});const candidateId=engine.recordId(frozen.candidate,'candidateFreezes');
  p.stages[18].status='COMPLETE';const confirmationIteration=engine.beginUnchangedConfirmationIteration(p,{candidateId});const confirmationId='CONFIRM-ARTIFACT-AUTHORITY';const confirmation=record('confirmationRecords',19,{SOURCE_ITERATION_ID:engine.recordValue(frozen.iteration,'ITERATION_ID'),CONFIRMATION_ITERATION_ID:engine.recordId(confirmationIteration,'iterations'),DETERMINATION:'SATISFIED'},confirmationId);confirmation.scope={...confirmationIteration.scope};p.projectData.confirmationRecords.push(confirmation);p.job.CURRENT_ITERATION=engine.recordId(confirmationIteration,'iterations');
  let rejected=false;try{engine.freezeBaseline(p,{artifactIds:['ART-UNRELATED']});}catch(error){rejected=/exactly match|unrelated|partial/i.test(String(error.message));}assert(rejected,'Stage 20 accepted baseline bytes outside the unchanged frozen candidate manifest.');
  const baseline=engine.freezeBaseline(p,{artifactIds:[]});assert(JSON.stringify(engine.recordValue(baseline,'IMMUTABLE_ARTIFACT_RECORDS'))===JSON.stringify(['ART-CANDIDATE']),'Stage 20 did not derive baseline artifact identity from the exact unchanged candidate manifest.');
  let productBytesRejected=false;const q=project('JOB-STAGE21-UNRESERVED');try{engine.registerArtifactBytes(q,{stage:21,artifactId:'ART-EARLY',filename:'result.pdf',mediaType:'application/pdf',byteSize:1,sha256:'cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc'});}catch(error){productBytesRejected=/Reserve the Stage 21 product execution/i.test(String(error.message));}assert(productBytesRejected,'Stage 21 accepted finished-product bytes before a product execution identity existed.');
}

"""
if anchor not in s: raise SystemExit('verify artifact anchor missing')
if 'JOB-ARTIFACT-AUTHORITY' not in s:s=s.replace(anchor,test+anchor,1)
p.write_text(s)

Path('repair-artifact-authority.py').unlink(missing_ok=True)
Path('.github/workflows/prove-artifact-authority.yml').unlink(missing_ok=True)
